function validate([board]) {
  if (!Array.isArray(board) || board.length < 1 || board.length > 200) return 'board needs 1 to 200 rows.';
  const width = board[0].length;
  if (width < 1 || width > 200) return 'Each row needs 1 to 200 cells.';
  if (board.some(row => row.length !== width)) return 'Every row must have the same length.';
  if (board.some(row => row.some(cell => cell !== '.' && cell !== 'X'))) return "Each cell is '.' or 'X'.";
  const ship = (r, c) => r >= 0 && r < board.length && c >= 0 && c < width && board[r][c] === 'X';
  for (let r = 0; r < board.length; r++) {
    for (let c = 0; c < width; c++) {
      // A ship cell with neighbours both across and along would bend the ship.
      const across = ship(r, c - 1) || ship(r, c + 1);
      const along = ship(r - 1, c) || ship(r + 1, c);
      if (ship(r, c) && across && along) return 'Every ship must be a straight line, and ships may not touch along an edge.';
    }
  }
  return null;
}

