function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const m = large ? 100 : 1 + pick(6);
  const n = large ? 100 : 1 + pick(6);
  const board = Array.from({ length: m }, () => new Array(n).fill('.'));
  const free = (r, c) => r < 0 || c < 0 || r >= m || c >= n || board[r][c] === '.';
  const attempts = large ? 4000 : pick(12);
  for (let t = 0; t < attempts; t++) {
    const across = rand() < 0.5;
    const length = 1 + pick(large ? 8 : 4);
    const r0 = pick(m), c0 = pick(n);
    const cells = [];
    for (let i = 0; i < length; i++) cells.push(across ? [r0, c0 + i] : [r0 + i, c0]);
    // A ship must fit, and none of its cells or their edge neighbours may already hold a ship.
    const fits = cells.every(([r, c]) => r < m && c < n && free(r, c) && free(r - 1, c) && free(r + 1, c) && free(r, c - 1) && free(r, c + 1));
    if (fits) for (const [r, c] of cells) board[r][c] = 'X';
  }
  return [board];
}
